describe('Search Functionality', () => {
    beforeEach(() => {
        cy.visit('/search');
    });

    it('should return results for a correctly spelled search term', () => {
        cy.get('input[name="search"]').type('laptop');
        cy.get('button[type="submit"]').click();
        cy.get('.search-results').should('contain', 'laptop');
    });

    it('should return results for a misspelled search term', () => {
        cy.get('input[name="search"]').type('laptp');
        cy.get('button[type="submit"]').click();
        cy.get('.search-results').should('contain', 'laptop');
        cy.get('.search-results').should('contain', 'laptops');
    });
});
